import subprocess
import json

test_cases = [
    {
        "name": "Example 1: Basic call with parameters",
        "input": {
            "defs": {
                "Normalize": { "steps":[
                    {"op":"map","as":"z","expr":"(value - params.mean) / params.std"}
                ]},
                "KeepCols": { "steps":[
                    {"op":"select","columns":["id","z"]}
                ]}
            },
            "pipeline": {
                "steps": [
                    {"op":"call","name":"Normalize","params":{"mean":100,"std":20}},
                    {"op":"call","name":"KeepCols","params":{}}
                ]
            },
            "dataset":[
                {"id":1,"value":120},
                {"id":2,"value":80}
            ]
        },
        "expected_status": "ok",
        "expected_data": [
            {"id":1,"z":1},
            {"id":2,"z":-1}
        ]
    },
    {
        "name": "Example 2: Missing definition",
        "input": {
            "defs": {},
            "pipeline": { "steps": [ {"op":"call","name":"Missing","params":{}} ] },
            "dataset":[{"id":1}]
        },
        "expected_status": "error",
        "expected_error_code": "UNKNOWN_DEF",
        "expected_path": "pipeline.steps[0].name"
    },
    {
        "name": "Example 3: Direct recursion",
        "input": {
            "defs": {
                "Loop": { "steps":[ {"op":"call","name":"Loop","params":{}} ] }
            },
            "pipeline": { "steps": [ {"op":"call","name":"Loop","params":{}} ] },
            "dataset":[{"id":1}]
        },
        "expected_status": "error",
        "expected_error_code": "RECURSION_FORBIDDEN",
        "expected_path": "defs[Loop].steps[0].name"
    }
]

for test in test_cases:
    result = subprocess.run(
        ["python", "etl_pipeline.py", "--execute"],
        input=json.dumps(test["input"]),
        text=True,
        capture_output=True
    )

    output = json.loads(result.stdout)

    # Check status
    if output.get("status") != test.get("expected_status"):
        print(f"FAIL: {test['name']}")
        print(f"  Expected status: {test.get('expected_status')}, got: {output.get('status')}")
        continue

    # If error, check error code and path
    if test.get("expected_status") == "error":
        if output.get("error_code") != test.get("expected_error_code"):
            print(f"FAIL: {test['name']}")
            print(f"  Expected error code: {test.get('expected_error_code')}, got: {output.get('error_code')}")
            continue
        if output.get("path") != test.get("expected_path"):
            print(f"FAIL: {test['name']}")
            print(f"  Expected path: {test.get('expected_path')}, got: {output.get('path')}")
            continue
    else:
        # Check data
        if output.get("data") != test.get("expected_data"):
            print(f"FAIL: {test['name']}")
            print(f"  Expected data: {test.get('expected_data')}, got: {output.get('data')}")
            continue

    print(f"PASS: {test['name']}")

PYEOF

