import subprocess
import json

backward_compat_tests = [
    {
        "name": "Select operation",
        "input": {
            "pipeline": {"steps": [{"op":"select","columns":["id"]}]},
            "dataset": [{"id":1,"name":"Alice"},{"id":2,"name":"Bob"}]
        },
        "expected": [{"id":1},{"id":2}]
    },
    {
        "name": "Filter operation",
        "input": {
            "pipeline": {"steps": [{"op":"filter","where":"id > 1"}]},
            "dataset": [{"id":1},{"id":2},{"id":3}]
        },
        "expected": [{"id":2},{"id":3}]
    },
    {
        "name": "Map operation",
        "input": {
            "pipeline": {"steps": [{"op":"map","as":"x","expr":"id * 2"}]},
            "dataset": [{"id":1},{"id":2}]
        },
        "expected": [{"id":1,"x":2},{"id":2,"x":4}]
    },
    {
        "name": "Rename operation",
        "input": {
            "pipeline": {"steps": [{"op":"rename","from":"id","to":"identifier"}]},
            "dataset": [{"id":1,"name":"Alice"}]
        },
        "expected": [{"identifier":1,"name":"Alice"}]
    },
    {
        "name": "Limit operation",
        "input": {
            "pipeline": {"steps": [{"op":"limit","n":2}]},
            "dataset": [{"id":1},{"id":2},{"id":3}]
        },
        "expected": [{"id":1},{"id":2}]
    },
    {
        "name": "Branch operation",
        "input": {
            "pipeline": {
                "steps": [{
                    "op":"branch",
                    "branches":[
                        {"when":"id > 1","steps":[{"op":"map","as":"type","expr":"'high'"}]},
                        {"when":"otherwise","steps":[{"op":"map","as":"type","expr":"'low'"}]}
                    ]
                }]
            },
            "dataset": [{"id":1},{"id":2}]
        },
        "expected": [{"id":2,"type":"high"},{"id":1,"type":"low"}]
    },
    {
        "name": "Complex pipeline",
        "input": {
            "pipeline": {
                "steps": [
                    {"op":"map","as":"doubled","expr":"id * 2"},
                    {"op":"filter","where":"doubled > 2"},
                    {"op":"select","columns":["id","doubled"]},
                    {"op":"limit","n":1}
                ]
            },
            "dataset": [{"id":1},{"id":2},{"id":3}]
        },
        "expected": [{"id":2,"doubled":4}]
    }
]

all_pass = True
for test in backward_compat_tests:
    result = subprocess.run(
        ["python", "etl_pipeline.py", "--execute"],
        input=json.dumps(test["input"]),
        text=True,
        capture_output=True
    )

    output = json.loads(result.stdout)

    if output.get("status") != "ok":
        print(f"FAIL: {test['name']} - got error: {output.get('error_code')}")
        all_pass = False
        continue

    if output.get("data") != test.get("expected"):
        print(f"FAIL: {test['name']}")
        print(f"  Expected: {test.get('expected')}")
        print(f"  Got:      {output.get('data')}")
        all_pass = False
        continue

    print(f"PASS: {test['name']}")

if all_pass:
    print("\n✓ All backward compatibility tests passed!")
else:
    print("\n✗ Some tests failed")

PYEOF
